   });

+  it('shifts absolute references at or after the insertion point and pins those before it', async () => {
+    // Contract v1.4 §3 boundary ①: a reference strictly above the insertion
+    // does not move, even when it is absolute.
+    const db = freshDb();
+    const app = appFor(db);
+    setCells(db, SEED_SHEET1_ID, [
+      { row: 0, col: 0, raw: '=$A$1' },
+      { row: 0, col: 1, raw: '=$A$4' },
+    ]);
+    const res = await request(app)
+      .post(`/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows`)
+      .send({ index: 2, count: 1, side: 'above' });
+    expect(res.status).toBe(200);
+    const cells = sheetCells(db, SEED_SHEET1_ID);
+    expect(cells).toContainEqual({ row: 0, col: 0, raw: '=$A$1' });
+    expect(cells).toContainEqual({ row: 0, col: 1, raw: '=$A$5' });
+  });
+
+  it('moves absolute references up on deletion and flags a deleted absolute target', async () => {
+    const db = freshDb();
+    const app = appFor(db);
+    setCells(db, SEED_SHEET1_ID, [
+      { row: 0, col: 0, raw: '=$A$3' },
+      { row: 0, col: 1, raw: '=$A$5' },
+    ]);
+    const res = await request(app).delete(
+      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/1`,
+    );
+    expect(res.status).toBe(200);
+    const cells = sheetCells(db, SEED_SHEET1_ID);
+    expect(cells).toContainEqual({ row: 0, col: 0, raw: '=$A$2' });
+    expect(cells).toContainEqual({ row: 0, col: 1, raw: '=$A$4' });
+
+    // Deleting the row an absolute reference points at replaces just that
+    // reference with `#REF!` (structure path is by-reference, not formula-wide).
+    setCells(db, SEED_SHEET1_ID, [{ row: 0, col: 0, raw: '=$A$2+1' }]);
+    const second = await request(app).delete(
+      `/api/workbooks/${SEED_WORKBOOK_ID}/worksheets/${SEED_SHEET1_ID}/rows/1`,
+    );
+    expect(second.status).toBe(200);
+    expect(sheetCells(db, SEED_SHEET1_ID)).toEqual([{ row: 0, col: 0, raw: '=#REF!+1' }]);
+  });
+
